package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
final class CommentSheet {
 static void show(Context c,String id){NativeSheet sheet=new NativeSheet(c,"Comentários");TextView state=NativeSheet.text(c,"Carregando…",13,0xffbba9e6);sheet.body.addView(state);LinearLayout comments=new LinearLayout(c);comments.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(comments);EditText draft=NativeSheet.input(c,"Escreva um comentário",240);sheet.body.addView(draft);Button send=new Button(c);send.setText("Comentar");AppStyle.button(send,true);sheet.body.addView(send);Runnable reload=()->new AccountRepository(c).comments(id,(rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){state.setText(error);return;}comments.removeAllViews();state.setText(rows.length()==0?"Seja o primeiro a comentar":"Até 100 comentários");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;TextView name=NativeSheet.text(c,"Membro",12,0xffbba9e6);comments.addView(name);JSONObject author=row.optJSONObject("_author");if(author!=null)name.setText(author.optString("nome","Membro"));comments.addView(NativeSheet.text(c,row.optString("texto",""),15,0xfff3eff9));}});send.setOnClickListener(v->{if(draft.getText().toString().trim().isEmpty()){state.setText("Escreva um comentário.");return;}send.setEnabled(false);sheet.busy(true);new AccountRepository(c).comment(id,draft.getText().toString(),(r,e)->{sheet.busy(false);if(e!=null){state.setText(e+" Confira os comentários antes de reenviar.");return;}send.setEnabled(true);draft.setText("");reload.run();});});sheet.show();reload.run();}
}
